/* rocklabel dashboard — view rendering, the run drawer, and job streaming.
 *
 * One page, no build step, no network dependency. The server is the source of
 * truth for both the command catalog and the command line a form produces, so
 * the preview you see in the drawer footer is generated by the same code that
 * builds the argv — it cannot drift.
 */
'use strict';

const S = {
  catalog: null,
  inv: null,
  machine: null,
  jobs: [],
  activeJob: null,
  jobCursor: 0,
  follow: true,
  view: 'overview',
  stageFilter: 'all',
  search: '',
  dataTab: 'recordings',
  metric: 'f1',
  drawerCmd: null,
  openRows: new Set(),
  showAllHelp: false,
  invSig: null,
};

/* ------------------------------------------------------------------ utils */
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

function h(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}
function frag() { return document.createDocumentFragment(); }

function fmtBytes(n) {
  if (!n) return '0 B';
  const u = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.min(u.length - 1, Math.floor(Math.log(n) / Math.log(1024)));
  const v = n / Math.pow(1024, i);
  return `${v >= 100 || i === 0 ? Math.round(v) : v.toFixed(1)} ${u[i]}`;
}
function fmtNum(n) {
  if (n == null) return '—';
  if (n >= 1e6) return `${(n / 1e6).toFixed(1)}M`;
  if (n >= 1e4) return `${(n / 1e3).toFixed(0)}K`;
  return n.toLocaleString();
}
function fmtAgo(ts) {
  if (!ts) return '—';
  const s = Date.now() / 1000 - ts;
  if (s < 60) return 'just now';
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  const d = Math.floor(s / 86400);
  if (d < 30) return `${d}d ago`;
  return new Date(ts * 1000).toLocaleDateString();
}
function fmtDur(s) {
  if (s == null) return '—';
  if (s < 60) return `${s.toFixed(0)}s`;
  const m = Math.floor(s / 60);
  return `${m}m ${Math.round(s - m * 60)}s`;
}

async function api(path, opts) {
  const res = await fetch(path, opts);
  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(body.error || `${res.status} ${res.statusText}`);
  return body;
}
async function post(path, data) {
  return api(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data || {}),
  });
}

function toast(msg, kind, action) {
  const box = $('#toasts');
  const t = h('div', `toast${kind === 'err' ? ' err' : ''}`);
  t.appendChild(h('span', null, msg));
  if (action) {
    const b = h('button', null, action.label);
    b.onclick = () => { action.fn(); t.remove(); };
    t.appendChild(b);
  }
  box.appendChild(t);
  setTimeout(() => t.remove(), action ? 8000 : 4200);
}

/* ------------------------------------------------------------------ theme */
function initTheme() {
  const saved = localStorage.getItem('rocklabel-theme');
  const theme = saved || (matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
  document.documentElement.dataset.theme = theme;
  $('#themeToggle').onclick = () => {
    const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
    document.documentElement.dataset.theme = next;
    localStorage.setItem('rocklabel-theme', next);
    render();                      // charts read their colors from CSS vars
  };
}

/* ---------------------------------------------------------------- routing */
function setView(name) {
  S.view = name;
  $$('.nav-item').forEach((b) => b.classList.toggle('is-active', b.dataset.view === name));
  $$('.view').forEach((v) => v.classList.toggle('is-active', v.id === `view-${name}`));
  window.scrollTo({ top: 0, behavior: 'instant' });
  render();
}

/* ============================================================== OVERVIEW */
function renderOverview() {
  const t = S.inv.totals;

  const f1 = t.best_f1;
  $('#heroF1').textContent = f1 ? f1.toFixed(3) : '—';
  $('#heroF1Sub').textContent = f1
    ? `${t.best_model} · held out ${(S.inv.runs.find((r) => r.name === t.best_run) || {}).test_run || '?'} · ${t.runs_complete} of ${t.runs} folds evaluated`
    : 'no completed training runs yet';
  $('#heroF1Meter').style.width = `${Math.round((f1 || 0) * 100)}%`;

  const tiles = [
    { label: 'Recordings', value: t.recordings, sub: `${fmtBytes(t.recordings_bytes)} · ${t.recordings_labeled} labeled`, view: 'data', tab: 'recordings' },
    { label: 'Rocks labeled', value: t.rocks, sub: `across ${t.labels} label files`, view: 'data', tab: 'labels' },
    { label: 'Training samples', value: fmtNum(t.samples), sub: `${fmtNum(t.rock_samples)} rock · ${t.datasets} datasets`, view: 'data', tab: 'datasets' },
    { label: 'Training folds', value: `${t.runs_complete}/${t.runs}`, sub: 'evaluated / total', view: 'models' },
  ];
  const box = $('#tiles');
  box.innerHTML = '';
  tiles.forEach((tile) => {
    const b = h('button', 'tile');
    b.appendChild(h('div', 'stat-label', tile.label));
    b.appendChild(h('div', 'stat-value', String(tile.value)));
    b.appendChild(h('div', 'stat-sub', tile.sub));
    b.onclick = () => { if (tile.tab) S.dataTab = tile.tab; setView(tile.view); };
    box.appendChild(b);
  });

  // ---- pipeline flow
  const counts = {
    capture: { n: t.recordings, unit: t.recordings === 1 ? 'recording' : 'recordings' },
    triage: { n: t.recordings, unit: 'to inspect / trim' },
    label: { n: t.rocks, unit: t.rocks === 1 ? 'rock labeled' : 'rocks labeled' },
    dataset: { n: t.samples, unit: 'samples generated' },
    train: { n: t.runs_complete, unit: 'folds evaluated' },
    deploy: { n: S.inv.checkpoints.filter((c) => c.name.endsWith('best.pt')).length, unit: 'checkpoints ready' },
  };
  const flow = $('#flow');
  flow.innerHTML = '';
  S.catalog.stages.forEach((st) => {
    const c = counts[st.id] || { n: 0, unit: '' };
    const b = h('button', 'flow-stage');
    b.dataset.filled = c.n > 0 ? '1' : '0';
    const title = h('div', 'flow-title');
    title.appendChild(h('span', 'flow-dot'));
    title.appendChild(document.createTextNode(st.title));
    b.appendChild(title);
    b.appendChild(h('div', 'flow-count', fmtNum(c.n)));
    b.appendChild(h('div', 'flow-blurb', c.unit || st.blurb));
    b.title = st.blurb;
    b.onclick = () => { S.stageFilter = st.id; setView('commands'); };
    flow.appendChild(b);
  });

  // ---- quick actions
  const quick = [
    ['live', 'Open the live view', 'Watch the sensor, with or without a model.'],
    ['record', 'Record a run', 'Capture straight to an .mcap.'],
    ['label', 'Label a recording', 'Place rock labels on the fused cloud.'],
    ['generate', 'Generate a dataset', 'Turn labels into training data.'],
  ];
  const qbox = $('#quickActions');
  qbox.innerHTML = '';
  quick.forEach(([id, title, desc]) => qbox.appendChild(quickButton(id, title, desc)));

  // ---- recent activity
  const items = [];
  S.inv.recordings.slice(0, 5).forEach((r) => items.push({ kind: 'recording', name: r.name, ts: r.mtime }));
  S.inv.labels.slice(0, 5).forEach((l) => items.push({ kind: 'labels', name: `${l.name} · ${l.rock_count} rocks`, ts: l.mtime }));
  S.inv.datasets.forEach((d) => items.push({ kind: 'dataset', name: d.name, ts: d.mtime }));
  S.inv.runs.filter((r) => r.complete).forEach((r) => items.push({ kind: 'model', name: `${r.name} · F1 ${(r.metrics.f1 || 0).toFixed(3)}`, ts: r.mtime }));
  items.sort((a, b) => b.ts - a.ts);
  const list = $('#activity');
  list.innerHTML = '';
  if (!items.length) list.appendChild(h('li', 'muted', 'Nothing here yet — start with a recording.'));
  items.slice(0, 9).forEach((it) => {
    const li = h('li');
    li.appendChild(h('span', 'act-kind', it.kind));
    li.appendChild(h('span', 'act-name', it.name));
    li.appendChild(h('span', 'act-when', fmtAgo(it.ts)));
    list.appendChild(li);
  });
}

function quickButton(cmdId, title, desc, prefill) {
  const cmd = S.catalog.commands.find((c) => c.id === cmdId);
  const b = h('button', 'quick-btn');
  const icon = h('div', 'quick-icon', cmd ? cmd.icon : '▸');
  b.appendChild(icon);
  const txt = h('div');
  txt.appendChild(h('div', 'quick-title', title));
  txt.appendChild(h('div', 'quick-desc', desc));
  b.appendChild(txt);
  b.onclick = () => openDrawer(cmdId, prefill);
  return b;
}

/* ============================================================== COMMANDS */
function renderCommands() {
  const chips = $('#stageChips');
  if (!chips.dataset.built) {
    const all = [{ id: 'all', title: 'All' }, ...S.catalog.stages];
    all.forEach((st) => {
      const c = h('button', 'chip', st.title);
      c.dataset.stage = st.id;
      c.onclick = () => { S.stageFilter = st.id; renderCommands(); };
      chips.appendChild(c);
    });
    chips.dataset.built = '1';
    $('#cmdSearch').addEventListener('input', (e) => {
      S.search = e.target.value.toLowerCase();
      renderCommands();
    });
  }
  $$('.chip', chips).forEach((c) => c.classList.toggle('is-active', c.dataset.stage === S.stageFilter));

  const wrap = $('#commandGroups');
  wrap.innerHTML = '';
  const q = S.search;
  const matches = (c) => (S.stageFilter === 'all' || c.stage === S.stageFilter)
    && (!q || `${c.title} ${c.cli} ${c.tagline} ${c.what}`.toLowerCase().includes(q));

  let shown = 0;
  S.catalog.stages.forEach((stage) => {
    const cmds = S.catalog.commands.filter((c) => c.stage === stage.id && matches(c));
    if (!cmds.length) return;
    shown += cmds.length;
    const group = h('section', 'cmd-group');
    const head = h('div', 'cmd-group-head');
    head.appendChild(h('h2', null, stage.title));
    head.appendChild(h('span', null, stage.blurb));
    group.appendChild(head);
    const grid = h('div', 'cmd-grid');
    cmds.forEach((c) => grid.appendChild(commandCard(c)));
    group.appendChild(grid);
    wrap.appendChild(group);
  });
  if (!shown) {
    const empty = h('div', 'empty');
    empty.appendChild(h('strong', null, 'No commands match'));
    empty.appendChild(h('div', null, 'Try a different search or clear the stage filter.'));
    wrap.appendChild(empty);
  }
}

function commandCard(c) {
  const card = h('button', 'cmd-card');
  const top = h('div', 'cmd-card-top');
  top.appendChild(h('div', 'cmd-icon', c.icon));
  const names = h('div');
  names.appendChild(h('div', 'cmd-name', c.title));
  names.appendChild(h('div', 'cmd-cli', c.cli));
  top.appendChild(names);
  card.appendChild(top);
  card.appendChild(h('div', 'cmd-tagline', c.tagline));
  const flags = h('div', 'cmd-flags');
  if (c.gui) flags.appendChild(h('span', 'flag gui', 'opens a window'));
  if (c.long_running) flags.appendChild(h('span', 'flag slow', 'long running'));
  const n = c.params.filter((p) => !p.advanced).length;
  flags.appendChild(h('span', 'flag', `${n} option${n === 1 ? '' : 's'}`));
  card.appendChild(flags);
  card.onclick = () => openDrawer(c.id);
  return card;
}

/* ================================================================== LIVE */
let sensorTimer = null;

function renderLive() {
  const box = $('#liveActions');
  if (!box.dataset.built) {
    const pre = { z_min: -1.5, z_max: -0.5, max_range: 8, source: 'udp' };
    box.appendChild(quickButton('live', 'Live view', 'Sensor stream, no recording.', pre));
    box.appendChild(quickButton('record', 'Record now', 'Capture straight to disk.', pre));
    const best = S.inv.checkpoints.find((c) => c.name.endsWith('best.pt'));
    box.appendChild(quickButton('live', 'Live + model', 'Score the live cloud as you sweep.',
      { ...pre, model: best ? best.path : '', color_mode: 'model' }));
    box.appendChild(quickButton('live', 'Replay a recording', 'Same pipeline, from a file.',
      { ...pre, play: (S.inv.recordings[0] || {}).path || '' }));
    box.dataset.built = '1';
    $('#liveHint').innerHTML =
      'The handheld presets assume the sensor sits about <b>1&nbsp;m above the floor</b> ' +
      '(<code>--z-min -1.5 --z-max -0.5 --max-range 8</code>). Adjust them in the drawer ' +
      'if the rig is mounted differently.';
  }
  refreshSensor();
  if (!sensorTimer) sensorTimer = setInterval(refreshSensor, 5000);
  renderControlPanel();
  renderLiveJobs();
}

/* The live control panel of whichever capture/viewer is running, embedded.
 *
 * `panel_url` appears on the job only once the child process has announced it
 * is serving, so there is no window where this frames a dead port.
 *
 * The one rule here: never reassign src for a URL that is already loaded. This
 * runs on every 5 s poll, and re-setting src reloads the page inside the frame
 * — which would throw away the user's scroll position and reset any control
 * they were mid-drag on, twelve times a minute. */
function renderControlPanel() {
  const card = $('#panelCard');
  const frame = $('#panelFrame');
  const job = S.jobs.find((j) => j.status === 'running' && j.panel_url);

  if (!job) {
    card.hidden = true;
    if (frame.dataset.src) {          // release the dead panel
      frame.removeAttribute('src');
      delete frame.dataset.src;
    }
    return;
  }

  card.hidden = false;
  $('#panelTitle').textContent = `${job.title} · controls`;
  $('#panelSub').textContent =
    `${job.id} — the 3D window is on your desktop; everything that steers it is here.`;
  if (frame.dataset.src !== job.panel_url) {
    frame.dataset.src = job.panel_url;
    frame.src = job.panel_url;
  }
  if (!card.dataset.wired) {
    card.dataset.wired = '1';
    $('#panelPop').onclick = () => {
      if (frame.dataset.src) window.open(frame.dataset.src, '_blank', 'noopener');
    };
    $('#panelReload').onclick = () => { frame.src = frame.dataset.src; };
  }
}

async function refreshSensor() {
  if (S.view !== 'live' || document.hidden) return;
  const body = $('#sensorBody');
  let s;
  try {
    s = await api('/api/sensor');
  } catch (e) {
    body.innerHTML = '';
    body.appendChild(h('div', 'muted', `probe failed: ${e.message}`));
    return;
  }

  body.innerHTML = '';
  const head = h('div', 'sensor-headline');
  const glyph = { streaming: '◉', idle: '◌', busy: '◑', offline: '✕', unknown: '?' }[s.state];
  head.appendChild(h('div', `sensor-dot ${s.state}`, glyph));
  const meta = h('div');
  meta.appendChild(h('div', 'sensor-state', s.label));
  meta.appendChild(h('div', 'muted', `${s.sensor_ip} · udp/${s.udp_port}`));
  head.appendChild(meta);
  body.appendChild(head);

  const checks = [
    { name: 'Reachable (ICMP)',
      ok: s.ping.reachable,
      detail: s.ping.detail + (s.ping.rtt_ms != null ? ` · ${s.ping.rtt_ms} ms` : '') },
    { name: 'Streaming Compact data',
      ok: s.listen.streaming,
      detail: s.listen.detail },
    { name: 'Host on the sensor subnet',
      ok: s.same_subnet,
      detail: s.interfaces.length
        ? s.interfaces.map((i) => `${i.name} ${i.address}`).join(' · ')
        : 'no non-loopback interfaces found' },
  ];
  checks.forEach((c) => {
    const row = h('div', 'check-row');
    const icon = h('div', 'check-icon', c.ok === true ? '✓' : c.ok === false ? '✕' : '–');
    icon.style.color = c.ok === true ? 'var(--good)'
      : c.ok === false ? 'var(--critical)' : 'var(--text-muted)';
    row.appendChild(icon);
    const txt = h('div');
    txt.appendChild(h('div', 'check-name', c.name));
    txt.appendChild(h('div', 'check-detail', c.detail));
    row.appendChild(txt);
    body.appendChild(row);
  });

  if (s.state === 'offline') {
    body.appendChild(hint('The sensor is not answering. Check power and the Ethernet link, ' +
      'then confirm this machine has an address on the sensor\'s subnet — that is the usual culprit.'));
  } else if (s.state === 'idle') {
    body.appendChild(hint('Powered and reachable, but nothing is arriving on the Compact port. ' +
      'Check the SOPAS output configuration: destination host and port must point here.'));
  } else if (s.state === 'busy') {
    body.appendChild(hint('A live job owns the UDP port right now, so the streaming check is ' +
      'skipped — read that job\'s throughput below instead.'));
  }

  const fix = s.network_fix;
  if (fix && fix.suggested) {
    body.appendChild(netFixBlock(fix));
  } else if (fix && fix.link_down) {
    // Addressing is right, the cable is not: no script would help here.
    body.appendChild(hint(`No carrier on ${fix.iface} — its addresses are set up correctly, ` +
      'so this is the cable or the sensor\'s power, not the network configuration.'));
  }
}

/* The wired NIC is misconfigured and no data is arriving: show what is wrong
 * and the script that fixes it. Deliberately copy-to-clipboard rather than a
 * "Fix it" button — every step needs root, and `ip addr flush` on the wrong
 * interface is how you drop your ssh session. */
function netFixBlock(fix) {
  const box = h('div', 'netfix');
  const head = h('div', 'netfix-head');
  head.appendChild(h('div', 'netfix-title',
    `Wired link to the sensor looks misconfigured${fix.iface ? ` (${fix.iface})` : ''}`));
  const copy = h('button', 'btn btn-sm', 'Copy commands');
  copy.onclick = async () => {
    try {
      await navigator.clipboard.writeText(fix.script);
      toast('Repair commands copied — paste them into a terminal.');
    } catch { toast('Could not access the clipboard.', 'err'); }
  };
  head.appendChild(copy);
  box.appendChild(head);

  const why = h('ul', 'netfix-problems');
  (fix.problems || []).forEach((p) => why.appendChild(h('li', null, p)));
  if (why.children.length) box.appendChild(why);

  box.appendChild(h('div', 'netfix-lead',
    'Plugged straight into a laptop there is no DHCP on that cable, so NetworkManager ' +
    'keeps retrying and tearing the addresses back down. Take the port away from it and ' +
    'set the addresses by hand — run these in a terminal, then re-check:'));

  const pre = h('pre', 'netfix-script');
  (fix.commands || []).forEach((c) => {
    pre.appendChild(h('span', 'netfix-why', `# ${c.why}\n`));
    pre.appendChild(h('span', 'netfix-cmd', `${c.cmd}\n`));
  });
  box.appendChild(pre);

  const again = h('button', 'btn btn-sm', 'Re-check now');
  again.onclick = () => refreshSensor();
  box.appendChild(again);
  return box;
}

function hint(text) {
  const d = h('div', 'hint');
  d.textContent = text;
  return d;
}

function renderLiveJobs() {
  const box = $('#liveJobs');
  box.innerHTML = '';
  const live = S.jobs.filter((j) => ['live', 'record'].includes(j.command_id));
  if (!live.length) {
    const e = h('div', 'empty');
    e.appendChild(h('strong', null, 'No capture or viewer running'));
    e.appendChild(h('div', null, 'Launch one above and its output shows up here.'));
    box.appendChild(e);
    return;
  }
  live.slice(0, 6).forEach((j) => {
    const row = h('div', 'check-row');
    row.style.alignItems = 'center';
    const st = h('span', `status status-${j.status}`, j.status);
    const txt = h('div');
    txt.style.flex = '1';
    txt.appendChild(h('div', 'check-name', `${j.title} · ${j.id}`));
    txt.appendChild(h('code', 'check-detail', j.command_line));
    row.appendChild(st);
    row.appendChild(txt);
    // Every job in this list is a panel command, so a running one either has
    // its controls up or is a second away from having them. Saying which beats
    // leaving a gap where a button is about to appear.
    if (j.status === 'running') {
      if (j.panel_url) {
        const controls = h('button', 'btn btn-sm', 'Controls');
        controls.title = 'Show this job’s control panel above';
        controls.onclick = () => {
          renderControlPanel();
          const card = $('#panelCard');
          if (card.scrollIntoView) card.scrollIntoView({ behavior: 'smooth' });
        };
        row.appendChild(controls);
      } else {
        row.appendChild(h('span', 'check-detail', 'panel starting…'));
      }
    }
    const open = h('button', 'btn btn-sm', 'Open log');
    open.onclick = () => { selectJob(j.id); setView('jobs'); };
    row.appendChild(open);
    if (j.status === 'running') {
      const stop = h('button', 'btn btn-sm btn-danger', 'Stop');
      stop.onclick = () => stopJob(j.id);
      row.appendChild(stop);
    }
    box.appendChild(row);
  });
}

/* ================================================================== DATA */
function renderData() {
  $$('#dataTabs .tab').forEach((t) => {
    t.classList.toggle('is-active', t.dataset.tab === S.dataTab);
    if (!t.dataset.wired) {
      t.dataset.wired = '1';
      t.onclick = () => { S.dataTab = t.dataset.tab; renderData(); };
    }
  });
  $$('.tab-panel').forEach((p) => p.classList.toggle('is-active', p.id === `tab-${S.dataTab}`));
  if (S.dataTab === 'recordings') renderRecordings();
  if (S.dataTab === 'labels') renderLabels();
  if (S.dataTab === 'datasets') renderDatasets();
}

function emptyState(title, body) {
  const e = h('div', 'empty');
  e.appendChild(h('strong', null, title));
  e.appendChild(h('div', null, body));
  return e;
}

function table(headers) {
  const wrap = h('div', 'table-wrap');
  const t = h('table');
  const thead = h('thead');
  const tr = h('tr');
  headers.forEach((head) => {
    const th = h('th', head.num ? 'num' : '', head.label);
    if (head.width) th.style.width = head.width;
    tr.appendChild(th);
  });
  thead.appendChild(tr);
  t.appendChild(thead);
  const tbody = h('tbody');
  t.appendChild(tbody);
  wrap.appendChild(t);
  return { wrap, tbody, cols: headers.length };
}

function detailItem(label, value) {
  const d = h('div', 'detail-item');
  d.appendChild(h('div', 'stat-label', label));
  d.appendChild(h('div', 'detail-value', value == null || value === '' ? '—' : String(value)));
  return d;
}

/** Expandable row: owns the detail <tr>, the caret glyph, and the open-set entry.
 *
 * `S.openRows` is keyed by path/name rather than row index so a row survives a
 * re-render — the poll rebuilds these tables whenever the inventory moves.
 * `fill` runs at most once per built row.
 */
function expandable(tbody, tr, key, fill, caret) {
  const detail = h('tr', 'row-detail');
  const td = h('td');
  td.colSpan = 99;
  const inner = h('div', 'row-detail-inner');
  td.appendChild(inner);
  detail.appendChild(td);
  let filled = false;

  const apply = (open) => {
    detail.hidden = !open;
    tr.classList.toggle('is-open', open);
    if (caret) caret.textContent = open ? '▾' : '▸';
    if (open) {
      S.openRows.add(key);
      if (!filled) { filled = true; fill(inner); }
    } else S.openRows.delete(key);
  };
  const toggle = () => apply(detail.hidden);
  apply(S.openRows.has(key));

  if (caret) caret.onclick = (e) => { e.stopPropagation(); toggle(); };
  tbody.appendChild(tr);
  tbody.appendChild(detail);
  return toggle;
}

function renderRecordings() {
  const panel = $('#tab-recordings');
  panel.innerHTML = '';
  const recs = S.inv.recordings;
  if (!recs.length) {
    panel.appendChild(emptyState('No recordings yet',
      'Drop an .mcap into recordings/, or run Record to capture one.'));
    return;
  }

  const card = h('div', 'card');
  const head = h('div', 'card-head');
  head.appendChild(h('h2', null, `${recs.length} recordings · ${fmtBytes(recs.reduce((a, r) => a + r.size, 0))}`));
  head.appendChild(h('p', 'card-sub',
    'Click a row to read its index: format, duration, topics and point density. '
    + 'Labels are matched by filename, so Rename moves the label file with the '
    + 'recording and rewrites the run id inside it. Delete removes only the '
    + 'recording.'));
  card.appendChild(head);

  const { wrap, tbody } = table([
    { label: '', width: '28px' }, { label: 'Recording' }, { label: 'Size', num: true },
    { label: 'Modified', num: true }, { label: 'Labels' }, { label: 'Actions' },
  ]);

  recs.forEach((r) => {
    const tr = h('tr');
    const expTd = h('td');
    const exp = h('button', 'expander', '▸');
    expTd.appendChild(exp);
    tr.appendChild(expTd);

    const nameTd = h('td');
    const nameBox = h('div');
    nameBox.appendChild(h('div', null, r.name));
    nameBox.appendChild(h('div', 'muted mono', r.path));
    nameTd.appendChild(nameBox);
    tr.appendChild(nameTd);
    tr.appendChild(h('td', 'num', fmtBytes(r.size)));
    tr.appendChild(h('td', 'num nowrap', fmtAgo(r.mtime)));

    const labTd = h('td');
    const lab = r.labels ? S.inv.labels.find((l) => l.path === r.labels) : null;
    if (lab) {
      const p = h('span', 'pill rock', `${lab.rock_count} rocks`);
      labTd.appendChild(p);
    } else {
      labTd.appendChild(h('span', 'muted', 'unlabeled'));
    }
    tr.appendChild(labTd);

    const actTd = h('td');
    const acts = h('div', 'row-actions');
    [['inspect', 'Inspect', { mcap: r.path }],
     ['label', 'Label', { mcap: r.path }],
     ['generate', 'Generate', { mcap: r.path, out: `datasets/${r.stem}` }],
     ['live', 'Replay', { play: r.path }],
    ].forEach(([id, label, pre]) => {
      const b = h('button', 'btn btn-sm', label);
      b.onclick = (e) => { e.stopPropagation(); openDrawer(id, pre); };
      acts.appendChild(b);
    });
    // Renaming a recording carries its labels along — see inventory._target.
    const keep = itemControls({
      kind: 'recording', name: r.stem, path: r.path,
      warn: `${fmtBytes(r.size)} goes for good; you cannot re-label or `
          + `re-generate from it afterwards.`
          + (r.labels ? ' Its label file stays behind.' : ''),
    }, nameBox);
    keep.triggers.forEach((b) => acts.appendChild(b));
    keep.panels.forEach((p) => nameTd.appendChild(p));
    actTd.appendChild(acts);
    tr.appendChild(actTd);

    const toggle = expandable(tbody, tr, `rec:${r.path}`, (inner) => {
      inner.appendChild(h('div', 'muted', 'reading index…'));
      api(`/api/recording?path=${encodeURIComponent(r.path)}`).then((info) => {
        inner.innerHTML = '';
        if (!info.ok) {
          inner.appendChild(h('div', 'status status-bad', `unreadable: ${info.error}`));
          if (info.hint) inner.appendChild(hint(info.hint));
          const b = h('button', 'btn btn-sm', 'Open Trim to salvage it');
          b.style.marginTop = '10px';
          b.onclick = () => openDrawer('trim', { mcap: r.path, out: `recordings/${r.stem}.fixed.mcap`, all_topics: true });
          inner.appendChild(b);
          return;
        }
        const grid = h('div', 'detail-grid');
        grid.appendChild(detailItem('Format', info.format));
        grid.appendChild(detailItem('Duration', `${info.duration_s.toFixed(1)} s`));
        grid.appendChild(detailItem('Messages', info.messages.toLocaleString()));
        grid.appendChild(detailItem('Recorded', (info.start || '').replace('T', ' ').replace('+00:00', ' UTC')));
        if (info.points_per_frame != null) {
          grid.appendChild(detailItem('Points / frame', info.points_per_frame.toLocaleString()));
          grid.appendChild(detailItem('Reflectivity', info.reflectivity ? `yes (peak ${info.reflectivity_peak})` : 'no'));
          grid.appendChild(detailItem('Poses', info.poses ? 'yes' : 'NO — SLAM never locked'));
        }
        inner.appendChild(grid);

        if (info.topics.length) {
          const tw = h('details');
          tw.style.marginTop = '12px';
          tw.appendChild(h('summary', null, `${info.topics.length} topics`));
          const tt = table([{ label: 'Topic' }, { label: 'Schema' }, { label: 'Messages', num: true }]);
          tt.wrap.style.marginTop = '8px';
          info.topics.forEach((tp) => {
            const row = h('tr');
            row.appendChild(h('td', 'mono', tp.topic));
            row.appendChild(h('td', 'muted mono', tp.schema));
            row.appendChild(h('td', 'num', tp.messages.toLocaleString()));
            tt.tbody.appendChild(row);
          });
          tw.appendChild(tt.wrap);
          inner.appendChild(tw);
        }
        if (info.pose_hint) inner.appendChild(hint(info.pose_hint));
      }).catch((e) => { inner.innerHTML = ''; inner.appendChild(h('div', 'status status-bad', e.message)); });
    }, exp);
    nameTd.style.cursor = 'pointer';
    nameTd.onclick = toggle;
  });

  card.appendChild(wrap);
  panel.appendChild(card);
}

